def apply(rel, txt):
    if rel not in HUNKS:
        raise SystemExit('kikar_745: no hunk on ' + rel)
    for a, b in HUNKS[rel]:
        if txt.count(a) != 1:
            raise SystemExit('kikar_745: FATAL anchor x%d in %s: %r' % (txt.count(a), rel, a[:60]))
        txt = txt.replace(a, b)
    print('[hunk] %s: %d hunk(s)' % (rel, len(HUNKS[rel])))
    return txt


